// ======================================================
// PREPARE CHAT QUESTION
// German Property Investment - RAG Chat
//
// Supports:
// 1. n8n Chat Trigger
// 2. HTTP Webhook
//
// Dynamic property identification
// No hardcoded property IDs
// ======================================================

const input = $input.first().json;

// Webhook requests normally place JSON inside body.
// Chat Trigger supplies fields directly.
const data =
  input.body &&
  typeof input.body === 'object'
    ? input.body
    : input;

// 1. Extract question
const chatInput = String(
  data.chatInput ??
  data.question ??
  data.message ??
  ''
).trim();

// 2. Extract property ID
const propertyId = String(
  data.property_id ??
  data.propertyId ??
  ''
).trim();

// 3. Extract session ID
const sessionId = String(
  data.sessionId ??
  data.session_id ??
  ''
).trim();

// 4. Validate
if (!chatInput) {
  throw new Error(
    'Missing chatInput. Send a question.'
  );
}

if (!propertyId) {
  throw new Error(
    'Missing property_id. Chat must be linked ' +
    'to an evaluated property.'
  );
}

if (!sessionId) {
  throw new Error(
    'Missing sessionId. Provide a unique ' +
    'conversation session identifier.'
  );
}

// 5. Return normalized input
return [{
  json: {
    chatInput,
    sessionId,
    property_id: propertyId,

    request_source:
      input.body ? 'webhook' : 'chat_trigger',

    request_ready: true
  }
}];

